import { Component, signal } from '@angular/core';
import { form, FormField, minLength, required } from '@angular/forms/signals';

@Component({
  selector: 'app-nueva-tarea',
  imports: [FormField],
  template: `
    <input [formField]="tareaForm.titulo" />
    @if (tareaForm.titulo().touched() && tareaForm.titulo().invalid()) {
      @for (e of tareaForm.titulo().errors(); track e.kind) {
        <small>{{ e.message }}</small>
      }
    }
    <button (click)="guardar()" [disabled]="tareaForm().invalid()">Crear</button>
  `,
})
export class NuevaTarea {
  readonly modelo = signal({ titulo: '', responsable: '' });

  readonly tareaForm = form(this.modelo, (campo) => {
    required(campo.titulo, { message: 'El título es obligatorio.' });
    minLength(campo.titulo, 3, { message: 'Escribí al menos 3 letras.' });
  });

  guardar() {
    console.log(this.modelo());   // el modelo YA tiene lo que se escribió
  }
}

